     figures:[['Prix total',money(c.investment)],['Rapporte en plus, frais enlevés',money(c.marginalHourly)+'/h'],['Remboursé après',c.breakEvenHours===null?'Jamais':hours(c.breakEvenHours)],['Différence après '+hours(H),money(c.difference)]],next,
     body:visual.roi(s,B.roi(s,sourceActivities),c),
     tradeoff:{title:'Avec ou sans cet achat, après '+hours(H)+' de jeu',html:table([['','Sans l’achat','Avec l’achat'],['Je paie au départ',money(0),money(c.investment)],['Je gagne par heure',c.baselineHourly===null?'—':money(c.baselineHourly),c.baselineHourly===null?'+ '+money(c.marginalHourly):money(c.baselineHourly+c.marginalHourly)],['Argent après '+hours(H),without,c.baselineHourly===null?'—':withB],['Différence','',money(c.difference)]],'Même argent au départ, même temps de jeu',true)+'<ul class="b-thresholds"><li>Il se rembourse après <b>'+(c.breakEvenHours===null?'jamais':hours(c.breakEvenHours))+'</b> de jeu'+(t.sessionsForPayback!==null?', soit <b>'+t.sessionsForPayback+' parties</b> de '+hours(s.goal.dailyMinutes/60):'')+'.</li><li>Pour être remboursé en '+hours(H)+', il devrait rapporter au moins <b>'+money(t.extraHourlyForHorizon)+' par heure</b> (frais compris).</li></ul>'},tradeoffOpen:true,
     assumptions:base.concat([{label:'Rapporte en plus',value:money(s.roi.revenueHourly)+'/h',origin:'toi',field:'f-roi-revenueHourly'},{label:'Coûte en plus',value:money(s.roi.costHourly)+'/h',origin:'toi',field:'f-roi-costHourly'},{label:'Temps où tu t’en sers',value:hours(H),origin:'toi',field:'f-roi-hours'}].concat(c.baselineHourly!==null?[{label:'Ce que tu gagnais déjà',value:money(c.baselineHourly)+'/h',origin:'toi',field:'f-goal-hourly'}]:[])),
