  if(Number.isFinite(s.goal.target))html+='<p>Après ces achats : '+money(r.finalCapital)+', encore '+money(Math.max(0,s.goal.target-(r.finalCapital-s.goal.reserve)))+' à gagner pour ton objectif.</p>';
