  html+='<h4>Selon ce qui compte</h4><ul class="b-compare-picks">'+[['value','Rapport envie / prix'],['cheapest','Le moins cher à l’achat'],['cheapestTotal','Le moins cher sur la durée'],['fastest','Le plus vite'],['profit','Se rembourse le plus vite'],['utility','Le plus d’envie']].map(([k,l])=>'<li><span>'+l+'</span><b>'+esc((k==='cheapestTotal'?(r.criterion==='cheapestTotal'?r.best:null):r.bestByCriterion[k])||'—')+'</b></li>').join('')+'</ul>';
