 function renderPlan(){compareRender();plan.render();}
 /* v7.47 (lot 10) : « Mes calculs enregistrés » dans un tiroir qui s'ouvre d'un clic depuis n'importe quel outil
    (bouton « Mes calculs » avec le nombre, en haut et en bas de l'atelier). Deux listes : les huit calculs et les
    business plans. Chaque carte montre l'outil, la date, le nom (modifiable), la réponse et trois chiffres clés.
    Deux cartes cochées se comparent côte à côte. Les clés de stockage ne changent pas (carnet v3). */
 const MONTHS=['janv.','févr.','mars','avr.','mai','juin','juil.','août','sept.','oct.','nov.','déc.'];
 const CRITERIA={value:'le meilleur rapport envie / prix',cheapest:'le moins cher',fastest:'le plus vite',profit:'qu’il se rembourse vite',utility:'celui dont j’ai le plus envie'};
