 const cash=v=>Number.isFinite(v)?money(v):'pas écrit';
 function longDate(v){const d=new Date(v);if(!Number.isFinite(d.getTime()))return String(v||'Date inconnue');return (d.getDate()===1?'1er':d.getDate())+'\u00a0'+MONTHS[d.getMonth()]+'\u00a0'+d.getFullYear()+' à '+d.getHours()+'\u00a0h\u00a0'+String(d.getMinutes()).padStart(2,'0');}
 function when(e){return Number.isFinite(Date.parse(e.updatedAt))?(e.updatedAt===e.createdAt?'Enregistré le ':'Modifié le ')+longDate(e.updatedAt):e.updatedAt;}
