  if(t==='roi')return [['Achat',a?.name||'pas choisi'],['Prix',cash(a?.price)],['Sur',hours(s.roi.hours)+' de jeu']];
  if(t==='compare')return [['Achats comparés',nf.format(s.compare.keys.length)],['Je veux surtout',CRITERIA[s.compare.criterion]||'pas choisi'],['J’ai',cash(g.capital)]];
