   +'<div class="b-notebook-head"><label class="calc-sr" for="entry-'+id+'">Nom du '+(kind==='plan'?'plan':'calcul')+'</label><input class="b-entry-name" id="entry-'+id+'" type="text" value="'+name+'" maxlength="100" autocomplete="off" data-b-rename="'+id+'"></div>'
